import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { InputText } from 'primereact/inputtext';
import { Password } from 'primereact/password';
import { Button } from 'primereact/button';
import { Message } from 'primereact/message';
import { useAuth } from '../../context/AuthContext';

const Login = () => {
    const [tendangnhap, setTendangnhap] = useState('');
    const [matkhau, setMatkhau] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tendangnhap || !matkhau) {
        setError('Vui lòng nhập đầy đủ thông tin');
        return;
    }
    setLoading(true);
    setError('');
    try {
        const result = await login(tendangnhap, matkhau);
        if (result.success) {
            const vaitro = result.user?.vaitro;
            if (vaitro === 'bep') {
                navigate('/kitchen');
            } else {
                navigate('/tables');
            }
        } else {
            setError(result.message);
        }
    } catch (err) {
        setError(err.response?.data?.message || 'Tên đăng nhập hoặc mật khẩu không đúng');
    } finally {
        setLoading(false);
    }
};

    return (
        <div className="min-h-screen flex align-items-center justify-content-center p-3" 
             style={{ background: 'radial-gradient(circle, #1a1a1a 0%, #080808 100%)' }}>
            
            <div className="p-5 shadow-8" 
                 style={{ 
                    width: '100%', 
                    maxWidth: '400px', 
                    background: '#121212', 
                    border: '1px solid rgba(201, 151, 58, 0.2)',
                    borderRadius: '4px',
                    boxShadow: '0 20px 50px rgba(0,0,0,0.5)'
                 }}>

                {/* Logo & Header */}
                <div className="text-center mb-6">
                    <div className="inline-flex align-items-center justify-content-center mb-3"
                         style={{ 
                            width: '56px', 
                            height: '56px', 
                            border: '1px solid #c9973a',
                            transform: 'rotate(45deg)',
                            marginBottom: '2rem'
                         }}>
                        <i className="pi pi-home" style={{ color: '#c9973a', fontSize: '1.5rem', transform: 'rotate(-45deg)' }} />
                    </div>
                    
                    <h2 style={{ 
                        fontFamily: "'Playfair Display', serif", 
                        fontSize: '24px', 
                        color: '#f0e6d3', 
                        letterSpacing: '4px',
                        margin: '0 0 10px 0',
                        fontWeight: '400'}}>
                        DCOFFE
                    </h2>
                    <div style={{ fontSize: '10px', color: '#888', letterSpacing: '5px', textTransform: 'uppercase' }}>
                        Hệ thống quản lý quán cà phê
                    </div>
                </div>

                {/* Form Nhập liệu */}
                <form onSubmit={handleSubmit} className="p-fluid">
                    {error && (
                        <div className="mb-4">
                            <Message severity="error" text={error} className="w-full justify-content-start" style={{ background: 'transparent', border: 'none', color: '#ff6b6b' }} />
                        </div>
                    )}

                    <div className="field mb-4">
                        <label htmlFor="username" style={{ fontSize: '10px', color: '#c9973a', letterSpacing: '2px', fontWeight: 'bold' }}>
                            TÊN ĐĂNG NHẬP
                        </label>
                        <span className="p-input-icon-left mt-2">
                            <i className="pi pi-user" style={{ color: '#444' }} />
                            <InputText
                                id="username"
                                value={tendangnhap}
                                onChange={e => setTendangnhap(e.target.value)}
                                placeholder="Username"
                                style={{ padding: '5px',background: '#1a1a1a', border: '1px solid #333', color: '#fff', paddingLeft: '30px' }}
                                autoFocus
                            />
                        </span>
                    </div>

                    <div className="field mb-5">
                        <label htmlFor="password" style={{ fontSize: '10px', color: '#c9973a', letterSpacing: '2px', fontWeight: 'bold' }}>
                            MẬT KHẨU
                        </label>
                        <span className="p-input-icon-left mt-2">
                            <i className="pi pi-lock" style={{ color: '#444', zIndex: 1 }} />
                            <Password
                                id="password"
                                value={matkhau}
                                onChange={e => setMatkhau(e.target.value)}
                                placeholder="Password"
                                inputStyle={{padding: '5px' ,background: '#1a1a1a', border: '1px solid #333', color: '#fff', paddingLeft: '25px' }}
                                toggleMask
                                feedback={false}
                            />
                        </span>
                    </div>

                    <Button
                        type="submit"
                        label={loading ? 'Đang đăng nhập...' : 'Đăng nhập'}
                        loading={loading}
                        style={{ 
                            background: '#c9973a',border: 'none', 
                            color: '#000',
                            fontWeight: 'bold',
                            padding: '10px',
                            borderRadius: '2px',
                            fontSize: '13px',
                            letterSpacing: '2px',
                            transition: 'all 0.3s'
                        }}
                        className="p-button-raised"
                    />
                </form>

                <div className="text-center mt-6" style={{ fontSize: '10px', color: '#444', letterSpacing: '1px' }}>
                    CUA HANG COFFE CUA DUC <br/>
                    <span className="mt-2 block">© {new Date().getFullYear()} DOANTN</span>
                </div>
            </div>
        </div>
    );
};

export default Login;
